uv run --no-project python - <<'PY'
from pathlib import Path
import importlib.util, sys
spec=importlib.util.spec_from_file_location('detect', Path('scripts/ci/detect_touched_domains.py').resolve())
mod=importlib.util.module_from_spec(spec); sys.modules['detect']=mod; spec.loader.exec_module(mod)
domains=mod.parse_domains(Path('tests/DOMAINS.md'))
roots=[r for d in domains for r in d.roots]
missing=[]
for p in sorted(Path('tests').iterdir(), key=lambda x: x.name):
    if p.name == '__pycache__':
        continue
    rel=p.as_posix() + ('/' if p.is_dir() else '')
    covered=False
    for root in roots:
        if root.endswith('/'):
            covered = rel.startswith(root) or root.startswith(rel)
        else:
            covered = rel.rstrip('/') == root or root.startswith(rel.rstrip('/') + '/')
        if covered:
            break
    if not covered:
        missing.append(rel)
print('uncovered top-level tests entries:', missing)
if missing:
    raise SystemExit(1)
